/* tailor showcase — wiring for the demo page. The showcase chrome is generated by bin/build (lib/showcase.js);
   this file adds: theme init from the embedded config, ?only=, scrollspy, and the demo-only interactions. */
(() => {
  const $ = (s, r = document) => r.querySelector(s), $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const C = window.TAILOR_SHOWCASE || {};
  Tailor.theme.init(C);
  Tailor.upgrade(document);

  const state = () => { const t = Tailor.theme.get(); $("#sc-state").textContent = `skin ${t.skin} · palette ${t.palette} · ${t.mode}`; $("#sc-core-note").hidden = t.skin !== "none"; };
  state(); document.documentElement.addEventListener("t:theme", state);

  // ?only=<component id>
  const params = new URLSearchParams(location.search), only = params.get("only");
  const keep = ["skin", "palette", "mode"].filter((k) => params.get(k)).map((k) => `${k}=${params.get(k)}`).join("&");
  if (only) {
    document.body.classList.add("sc-only");
    $$(".sc-component").forEach((s) => { s.hidden = s.id !== only; });
    $$("#sections-nav a").forEach((a) => { const id = a.getAttribute("href").slice(1); a.href = `?only=${id}${keep ? "&" + keep : ""}`; if (id === only) a.setAttribute("aria-current", "page"); });
    $(".sc-only-bar").hidden = false;
  } else Tailor.scrollspy($("#sections-nav"), $$(".sc-component"));
  $$("[data-only-link]").forEach((a) => { if (keep) a.href += "&" + keep; });

  // demo interactions (data-demo="…") — showcase only, never part of the contract
  document.addEventListener("click", (e) => {
    const el = e.target.closest("[data-demo]"); if (!el) return;
    switch (el.dataset.demo) {
      case "toggle": el.setAttribute("aria-pressed", el.getAttribute("aria-pressed") !== "true"); break;
      case "toast": Tailor.toast(el.dataset.toastTone, { success: "Saved and synced to health checks", warning: "Saved, DNS sync pending", danger: "DNS provider rejected the record: quota exceeded", info: "Next sync in 30 minutes" }[el.dataset.toastTone]); break;
      case "badge-toggle": el.dataset.tone = el.dataset.tone === "accent" ? "neutral" : "accent"; break;
      case "remove": el.closest(".t-chip").remove(); break;
      case "reveal": { const i = el.previousElementSibling; i.type = i.type === "password" ? "text" : "password"; break; }
      case "card-click": if (!e.target.closest("button")) Tailor.toast("info", "Card clicked: opens its detail"); break;
      case "stop": e.stopPropagation(); Tailor.toast("warning", "Stop requested"); break;
      case "dialog-save": Tailor.toast("success", "Saved"); break;
      case "confirm-danger": Tailor.confirm("Delete service?", "Removes the container, folder, DNS route and health check for <code>render</code>. This cannot be undone.", { label: "Delete" }).then((ok) => ok && Tailor.toast("success", "render deleted")); break;
      case "confirm-neutral": Tailor.confirm("Reboot epaper-display?", "The screen goes blank for about 20 seconds.", { label: "Reboot", danger: false }).then((ok) => Tailor.toast(ok ? "success" : "info", ok ? "Reboot sent" : "Cancelled")); break;
    }
  });
  $("[data-demo=form]")?.addEventListener("submit", (e) => { e.preventDefault(); Tailor.toast("success", "Valid — the form would submit now"); });
  $("[data-demo=range]")?.addEventListener("input", (e) => { $("#f-range-out").textContent = e.target.value + " %"; });
  $("[data-demo=codetabs]")?.addEventListener("t:change", (e) => { $("[data-demo=code-auth]").textContent = e.detail.tab.dataset.text; });
  const settings = $("[data-demo=settings]");
  if (settings) Tailor.settingsAutoSave(settings, (key, value) => new Promise((res) => setTimeout(() => res(key === "fail_demo" ? { ok: false, message: `${key}: rejected by the demo API (value "${value}")` } : { ok: true, message: `${key} saved` }), 500)));
  if (params.get("open") === "dialog") $("#demo-dlg")?.showModal();
  if (params.get("open") === "confirm") $("[data-demo=confirm-danger]")?.click();

  // dev self-check: duplicate ids break targets
  const seen = new Set(); $$("[id]").forEach((el) => { if (seen.has(el.id)) console.error("duplicate id", el.id); seen.add(el.id); });
})();
